import React, { useEffect, useState } from "react";
import axios from "axios";
import AlertBox from "./AlertBox";

function Courses() {
  const userId = localStorage.getItem("user_id");
  const role = localStorage.getItem("role");

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);

  const fetchCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      setCourses(res.data.courses || []);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchCourses();
  }, []);

  const handleEnroll = async (courseId) => {
    try {
      const res = await axios.post("http://127.0.0.1:8000/enroll", {
        user_id: parseInt(userId),
        course_id: courseId
      });

      setAlert({
        message: res.data.message,
        type: "success"
      });
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Enrollment failed",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2 style={{ color: "#4a148c", marginBottom: "20px" }}>
        All Courses
      </h2>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
          gap: "20px"
        }}
      >
        {courses.map((course) => (
          <div
            key={course.id}
            style={{
              background: "#fff",
              borderRadius: "16px",
              padding: "20px",
              boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
            }}
          >
            <h3 style={{ marginBottom: "10px" }}>{course.title}</h3>
            <p style={{ color: "#555" }}>{course.description}</p>

            <p>
              <strong>Subject Code:</strong> {course.subject_code}
            </p>

            <p>
              <strong>Created By:</strong> {course.created_by || "Unknown"}
            </p>

            <p style={{ color: "#777", fontSize: "14px" }}>
              <strong>Created At:</strong>{" "}
              {course.created_at
                ? new Date(course.created_at).toLocaleString()
                : "N/A"}
            </p>

            {role === "student" && (
              <button
                onClick={() => handleEnroll(course.id)}
                style={{
                  marginTop: "10px",
                  background: "#7b1fa2",
                  color: "#fff",
                  border: "none",
                  padding: "10px 14px",
                  borderRadius: "8px",
                  cursor: "pointer"
                }}
              >
                Enroll
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default Courses;
